// web/main/routes/ai.ts
async function aiRoutes(app) {
  app.post("/api/ai/translate-column", async (request) => {
    const { columnName, targetLocale } = request.body;
    if (!columnName) throw new Error("columnName is required");
    const target = (targetLocale || "zh-TW").trim();
    const phrase = columnName.replace(/[_-]+/g, " ").replace(/([a-z])([A-Z])/g, "$1 $2").toLowerCase().trim();
    const url = `https://translate.googleapis.com/translate_a/single?client=gtx&sl=auto&tl=${encodeURIComponent(target)}&dt=t&q=${encodeURIComponent(phrase)}`;
    const response = await fetch(url, {
      method: "GET",
      headers: { "user-agent": "Mozilla/5.0" }
    });
    if (!response.ok) {
      const err = await response.text();
      throw new Error(`Google Translate error ${response.status}: ${err.slice(0, 200)}`);
    }
    const data = await response.json();
    const segments = data[0] ?? [];
    const description = segments.map((s71) => s71[0]).join("").trim();
    if (!description) throw new Error("Empty translation result");
    return { description };
  });
}

// web/main/routes/application.ts
var fs = __toESM(require("fs"));

// web/main/libs/safeError.ts
function safeErrorMessage(err) {
  if (err instanceof Error) return err.message;
  return String(err);
}

// web/main/routes/application.ts
async function applicationRoutes(app) {
  app.post("/api/app/readFile", async (request) => {
    const { filePath, encoding } = request.body;
    try {
      const content = fs.readFileSync(filePath, encoding);
      return content;
    } catch (error) {
      return { status: "error", response: safeErrorMessage(error) };
    }
  });
  app.post("/api/app/writeFile", async (request) => {
    const { filePath, content } = request.body;
    try {
      fs.writeFileSync(filePath, content, "utf-8");
      return { status: "success" };
    } catch (error) {
      return { status: "error", response: safeErrorMessage(error) };
    }
  });
}

