// web/common/libs/sqlUtils.ts
var querySplitter = (sql, dbType) => {
  const queries = [];
  let currentQuery = "";
  let insideBlock = false;
  let insideString = false;
  let stringDelimiter = null;
  let insideDollarTag = false;
  let dollarTagDelimiter = null;
  const beginRegex = /\bBEGIN\b/i;
  const endRegex = /\bEND\b;/i;
  const dollarTagRegex = /\$(\w+)?\$/;
  const lines = sql.split(/(?<=;)/);
  for (let line of lines) {
    line = line.trim();
    if (!line) continue;
    for (let i62 = 0; i62 < line.length; i62++) {
      const char = line[i62];
      if ((char === "'" || char === '"') && (!insideString || char === stringDelimiter)) {
        if (!insideString) {
          insideString = true;
          stringDelimiter = char;
        } else {
          insideString = false;
          stringDelimiter = null;
        }
      }
      currentQuery += char;
      if (dbType === "pg") {
        if (!insideString && line.slice(i62).match(dollarTagRegex)) {
          const match = line.slice(i62).match(dollarTagRegex);
          if (match) {
            const tag = match[0];
            if (!insideDollarTag) {
              insideDollarTag = true;
              dollarTagDelimiter = tag;
              currentQuery += tag;
              i62 += tag.length - 1;
            } else if (dollarTagDelimiter === tag) {
              insideDollarTag = false;
              dollarTagDelimiter = null;
              currentQuery += tag;
              i62 += tag.length - 1;
            }
          }
        }
      }
      if (!insideString && !insideDollarTag) {
        if (beginRegex.test(line))
          insideBlock = true;
        if (insideBlock && endRegex.test(line))
          insideBlock = false;
      }
    }
    if (!insideBlock && !insideString && !insideDollarTag && /;\s*$/.test(line)) {
      queries.push(currentQuery.trim());
      currentQuery = "";
    }
  }
  if (currentQuery.trim())
    queries.push(currentQuery.trim());
  return queries;
};
var removeComments = (sql) => {
  let result = "";
  let insideSingleLineComment = false;
  let insideMultiLineComment = false;
  for (let i62 = 0; i62 < sql.length; i62++) {
    const char = sql[i62];
    const nextChar = sql[i62 + 1] || "";
    if (!insideMultiLineComment && char === "-" && nextChar === "-")
      insideSingleLineComment = true;
    if (!insideSingleLineComment && char === "/" && nextChar === "*") {
      insideMultiLineComment = true;
      i62++;
      continue;
    }
    if (insideMultiLineComment && char === "*" && nextChar === "/") {
      insideMultiLineComment = false;
      i62++;
      continue;
    }
    if (insideSingleLineComment) {
      if (char === "\n")
        insideSingleLineComment = false;
      continue;
    }
    if (insideMultiLineComment)
      continue;
    result += char;
  }
  return result;
};
var sqlEscaper = (string2) => {
  const pattern = /[\0\x08\x09\x1a\n\r"'\\\%]/gm;
  const regex = new RegExp(pattern);
  return string2.replace(regex, (char) => {
    const m74 = ["\\0", "\\x08", "\\x09", "\\x1a", "\\n", "\\r", "'", '"', "\\", "\\\\", "%"];
    const r52 = ["\\\\0", "\\\\b", "\\\\t", "\\\\z", "\\\\n", "\\\\r", "\\'", '\\"', "\\\\", "\\\\\\\\", "%"];
    return r52[m74.indexOf(char)] || char;
  });
};
var formatJsonForSqlWhere = (jsonValue, clientType) => {
  const formattedValue = JSON.stringify(jsonValue);
  switch (clientType) {
    case "mysql":
      return ` = CAST('${formattedValue}' AS JSON)`;
    case "maria":
      return ` = '${formattedValue}'`;
    case "pg":
      return `::text = '${formattedValue}'`;
    case "firebird":
    case "sqlite":
    default:
      return ` = '${formattedValue}'`;
  }
};

